import React, { useEffect, useState } from 'react';
import { getAssociatedFranchises, createUserExamData } from '../services/api'; // Updated import

const AssociatedFranchises = () => {
  const [examData, setExamData] = useState({
    franchiseId: '', // This will be populated with the user's associated franchiseId
    examName: '',
    date: '',
    studentsAttended: '',
  });
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const fetchUserFranchise = async () => {
      setLoading(true);
      try {
        const data = await getAssociatedFranchises(); // Use the correct function
        if (data && data.length > 0) {
          setExamData((prevData) => ({ ...prevData, franchiseId: data[0]._id })); // Assuming user can have multiple franchises, pick the first one
        } else {
          setError('No associated franchise found for the user.');
        }
      } catch (error) {
        setError('Failed to fetch the associated franchise.');
      } finally {
        setLoading(false);
      }
    };

    fetchUserFranchise();
  }, []); // Empty dependency array ensures this runs only once

  const handleExamDataChange = (e) => {
    setExamData({
      ...examData,
      [e.target.name]: e.target.value,
    });
  };

  const handleCreateExamData = async (e) => {
    e.preventDefault();

    // Validate the date
    if (!examData.date) {
      setError('Please provide the exam date.');
      return;
    }

    // Ensure the date is valid
    const examDate = new Date(examData.date);
    if (isNaN(examDate.getTime())) {
      setError('Invalid date format.');
      return;
    }

    setLoading(true);
    try {
      const formattedDate = examDate.toISOString().split('T')[0];
      await createUserExamData({ ...examData, date: formattedDate });
      setSuccess('Exam data created successfully!');
      setExamData({ franchiseId: '', examName: '', date: '', studentsAttended: '' });
      setError(null);
    } catch (error) {
      setError(error.response?.data?.message || 'Failed to create exam data.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (success) {
      const timer = setTimeout(() => setSuccess(''), 3000);
      return () => clearTimeout(timer);
    }
  }, [success]);

  return (
    <div>
      <h2>Associated Franchise</h2>
      {loading && <p>Loading...</p>}
      {error && <p style={{ color: 'red' }}>{error}</p>}
      {success && <p style={{ color: 'green' }}>{success}</p>}

      <h3>Create Exam Data</h3>
      <form onSubmit={handleCreateExamData}>
        {/* Franchise ID is now populated automatically based on the user's associated franchise */}
        <div>
          <label htmlFor="examName">Exam Name</label>
          <input
            type="text"
            name="examName"
            value={examData.examName}
            onChange={handleExamDataChange}
            required
          />
        </div>

        <div>
          <label htmlFor="date">Exam Date</label>
          <input
            type="date"
            name="date"
            value={examData.date}
            onChange={handleExamDataChange}
            required
          />
        </div>

        <div>
          <label htmlFor="studentsAttended">Students Attended</label>
          <input
            type="number"
            name="studentsAttended"
            value={examData.studentsAttended}
            onChange={handleExamDataChange}
            required
          />
        </div>

        <button type="submit" disabled={loading}>
          {loading ? 'Submitting...' : 'Create Exam Data'}
        </button>
      </form>
    </div>
  );
};

export default AssociatedFranchises;
